attribute float vertexId;
attribute float animationTime;
uniform sampler2D animationTexture;
void main() {
  vec2 uv = vec2(vertexId, animationTime);
  vec4 vertexPos = texture2D(animationTexture, uv);
  // Transform and project the vertex position
